  List<MapComposition.Layer> largeLayers=new ArrayList<>();String tail=new String(new char[2048-"https://tiles.example.org/{z}/{x}/{y}.png?padding=".length()]).replace('\0','q');for(int i=0;i<16;i++)largeLayers.add(MapComposition.Layer.custom(new TileSource("QA "+i,"https://tiles.example.org/{z}/{x}/{y}.png?padding="+tail,"QA",0,8,true)));MapComposition large=new MapComposition(7,largeLayers);ck((long)large.encode().length*16>MapCompositionPresets.MAX_BYTES);MapCompositionPresets bounded=empty;for(int i=0;i<16;i++)bounded=bounded.add("Large "+i,large);byte[] kept=presets.encode();final MapCompositionPresets tooLarge=bounded;refused(()->tooLarge.encode());ck(Arrays.equals(kept,presets.encode()));ck(Arrays.equals(original,composition.encode()));
  System.out.println("PASS map composition presets: "+n+" assertions");
